      '<div class="addrow"><div class="field wide"><label for="noteIn">Add a note</label><input class="in" id="noteIn" maxlength="400" placeholder="Called, promised to pay Friday…"></div><button type="button" class="btn sm" data-act="note" data-k="' + kind + '" data-v="' + o.id + '">Add</button></div>';
