      '<select class="select" id="apSort" aria-label="Sort"><option value="pay">By payment date</option><option value="amount">By amount</option><option value="supplier">By supplier</option></select></div>';
    h += '<section class="card"><div class="stats"><span><b>' + rows.length + '</b> shown</span><span><b>' + eur(sum(rows)) + '</b></span></div><div class="tw"><table class="t"><thead><tr><th>Bill</th><th>Supplier</th><th>Due</th><th>Status</th><th>Pay on</th><th class="num">Amount</th></tr></thead><tbody>' +
      (rows.length ? rows.map(function (r) {
        return '<tr class="click" data-act="openap" data-v="' + r.b.id + '" tabindex="0"><td class="nw mono">' + esc(r.b.no) + '</td><td class="name">' + esc(r.s.name) + (r.s.critical ? ' <span class="badge b-blue plain">Critical</span>' : '') + '</td><td class="nw">' + dt(r.b.due) + '</td><td>' + statusBadge(r.st, r.late) + '</td><td class="nw">' + (r.pay ? dt(r.pay) + (r.b.planned ? '<small>planned by you</small>' : '') : '<span class="muted">not in forecast</span>') + '</td><td class="num">' + eur2(r.b.amount) + '</td></tr>';
      }).join('') : '<tr><td colspan="6" class="empty">No bills match.</td></tr>') + '</tbody></table></div></section>';
