    body += '<p style="margin:12px 0 0">' + statusBadge(E.apStatus(b, TODAY), E.diffDays(b.due, TODAY)) + (s.critical ? ' <span class="badge b-blue plain">Critical supplier</span>' : '') + ' <span class="muted">Issued ' + dt(b.issued) + ' · ' + s.terms + '-day terms</span></p>';
    if (b.paid) body += '<div class="notice ok">Paid on ' + dt(b.paidOn) + '.</div>';
