  // ── CSV import ───────────────────────────────────────────────────────────
  function parseCsv(text) {
    text = text.replace(/^﻿/, '');
    var first = text.split(/\r?\n/)[0] || '', sep = (first.match(/;/g) || []).length >= (first.match(/,/g) || []).length ? ';' : ',';
    var rows = [], row = [], cell = '', q = false;
    for (var i = 0; i < text.length; i++) {
      var ch = text[i];
      if (q) { if (ch === '"') { if (text[i + 1] === '"') { cell += '"'; i++; } else q = false; } else cell += ch; }
      else if (ch === '"') q = true;
      else if (ch === sep) { row.push(cell); cell = ''; }
      else if (ch === '\n' || ch === '\r') { if (ch === '\r' && text[i + 1] === '\n') i++; row.push(cell); rows.push(row); row = []; cell = ''; }
      else cell += ch;
    }
    if (cell || row.length) { row.push(cell); rows.push(row); }
    return rows.filter(function (r) { return r.some(function (c) { return c.trim(); }); });
  }
  function parseDate(s) {
    s = String(s || '').trim();
    if (E.isDate(s)) return s;
    var m = /^(\d{1,2})\.\s*(\d{1,2})\.\s*(\d{4})$/.exec(s) || /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(s);
    if (m) { var d = m[3] + '-' + m[2].padStart(2, '0') + '-' + m[1].padStart(2, '0'); return E.isDate(d) ? d : null; }
    return null;
  }
  var importKind = 'ar';
  function importFile(text) {
    var rows = parseCsv(text), errs = [], out = [];
    if (!rows.length) return toast('The file is empty.');
    var hdr = rows[0].map(function (h) { return h.trim().toLowerCase(); });
    var col = function (names) { for (var i = 0; i < names.length; i++) { var k = hdr.indexOf(names[i]); if (k >= 0) return k; } return -1; };
    var cN = col(['number', 'invoice', 'bill', 'no']), cP = col(importKind === 'ar' ? ['customer', 'name'] : ['supplier', 'name']), cI = col(['issued', 'date']), cD = col(['due']), cA = col(['amount', 'total']);
    if (cN < 0 || cP < 0 || cD < 0 || cA < 0) return showImportErrors(['The first row must name the columns: number; ' + (importKind === 'ar' ? 'customer' : 'supplier') + '; issued; due; amount (download a template in Settings).']);
    rows.slice(1).forEach(function (r, i) {
      var line = i + 2, no = (r[cN] || '').trim(), party = (r[cP] || '').trim(), due = parseDate(r[cD]), issued = cI >= 0 ? parseDate(r[cI]) : null, amt = parseAmount(r[cA]);
      if (!no) errs.push('Row ' + line + ': number is missing.');
      if (!party) errs.push('Row ' + line + ': ' + (importKind === 'ar' ? 'customer' : 'supplier') + ' is missing.');
      if (!due) errs.push('Row ' + line + ': due date "' + (r[cD] || '') + '" is not a date (use 2026-10-31 or 31.10.2026).');
      if (!(amt > 0)) errs.push('Row ' + line + ': amount "' + (r[cA] || '') + '" is not a positive number.');
      out.push({ no: no, party: party, due: due, issued: issued || due, amount: Math.round(amt * 100) / 100 });
    });
    if (errs.length) return showImportErrors(errs);
    var list = importKind === 'ar' ? db.customers : db.suppliers, created = 0;
    commit('Imported ' + plural(out.length, importKind === 'ar' ? 'invoice' : 'bill', importKind === 'ar' ? 'invoices' : 'bills') + ' from CSV', function () {
      out.forEach(function (o, i) {
        var p = list.filter(function (x) { return x.name.toLowerCase() === o.party.toLowerCase(); })[0];
        if (!p) {
          created++;
          p = importKind === 'ar' ? { id: 'c' + Date.now().toString(36) + i, name: o.party, segment: 'Imported', terms: Math.max(0, E.diffDays(o.issued, o.due)), avgLate: 0, payments: [] } : { id: 's' + Date.now().toString(36) + i, name: o.party, terms: Math.max(0, E.diffDays(o.issued, o.due)), critical: false };
          list.push(p);
        }
        var id = (importKind === 'ar' ? 'ar' : 'ap') + Date.now().toString(36) + i;
        if (importKind === 'ar') db.ar.push({ id: id, no: o.no, customerId: p.id, issued: o.issued, due: o.due, amount: o.amount, paid: false, disputed: false, expected: '', notes: [] });
        else db.ap.push({ id: id, no: o.no, supplierId: p.id, issued: o.issued, due: o.due, amount: o.amount, paid: false, hold: false, planned: '', notes: [] });
      });
    });
    toast('Imported ' + plural(out.length, importKind === 'ar' ? 'invoice' : 'bill', importKind === 'ar' ? 'invoices' : 'bills') + (created ? ', ' + plural(created, importKind === 'ar' ? 'new customer' : 'new supplier', importKind === 'ar' ? 'new customers' : 'new suppliers') : ''));
  }
  function showImportErrors(errs) {
    modal('Nothing was imported', '<p>Fix these rows and try again. Either every row is imported or none.</p><ul class="imp-errs">' + errs.slice(0, 50).map(function (e) { return '<li>' + esc(e) + '</li>'; }).join('') + (errs.length > 50 ? '<li>… and ' + (errs.length - 50) + ' more</li>' : '') + '</ul>', 'OK', function () { closeLayer(); });
  }

